function _____57FA_7840_6838_5FC3_90E8_4EF6.prototype.____constructor(self)
    ActorTypeUtil:forAllActorTypes(
        function(____, actorType, index)
            actorType.onAction = function(____, actor)
                ____exports.default["基础强化核心部件"](____exports.default, actor)
            end
        end,
        "核心部件"
    )
    --- 伤害加成+30%（+5%）
    -- 力量加成+20%
    -- 主炮：
    -- 射程：800
    -- 伤害：攻击力x5
    -- 射速：0.8
    -- 强化+10：
    -- 力量加成+30%
    -- 强化+15：
    -- 重炮伤害翻倍。
    local actorType = nil
    actorType = ActorTypeUtil:getActorType("极限重炮")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.damage_increased = actor.level * 0.05 + 0.3
        actor.attribute.strength_p = actor.level >= 10 and 0.5 or 0.2
        local ctrl = actor.autoMissileAttackController
        if ctrl then
            ctrl.damageStateFormula.increased = actor.level >= 15 and 2 or 1
        end
    end
    actorType = ActorTypeUtil:getActorType("绝杀")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.attack_p = actor.level * 0.05 + 0.3
        if actor.level == 10 then
            SingletonUtil:executeOnce(
                "绝杀:" .. tostring(GetHandleId(actor.unit)),
                function()
                    PlayerUtil:message("绝杀：当前敏捷+15%，仅生效一次。", 5, actor.unitOwner)
                    HeroUtil:addHeroPropertyP(
                        actor.unit,
                        false,
                        0,
                        0.15,
                        0
                    )
                end
            )
        end
        local ctrl = actor.autoMissileAttackController
        if ctrl then
            if actor.level >= 15 then
                ctrl.onHitTarget = function(____, projectile)
                    if RandomUtil.isInChance(0.05) then
                        projectile.damage = projectile.damage * 10
                        TextTagUtil.textWarn("绝杀*10", projectile.target)
                    end
                end
            else
                ctrl.onHitTarget = nil
            end
        end
    end
    actorType = ActorTypeUtil:getActorType("巫术炮弹")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.magic_damage_increased = actor.level * 0.05 + 0.3
        local ctrl = actor.autoMissileAttackController
        if ctrl then
            if actor.level >= 10 then
                ctrl.onHitTarget = function(____, projectile)
                    if RandomUtil.isInChance(0.25) then
                        VestAbilityUtil:polymorph(projectile.target, 1)
                    end
                end
            else
                ctrl.onHitTarget = nil
            end
            ctrl.coolDown = actor.level >= 15 and 2.5 or 5
        end
    end
    actorType = ActorTypeUtil:getActorType("洲际导弹")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.full_property = actor.level * 1000 + 2000
        if actor.level >= 15 then
            actor.attribute.autoMissileAttackRange_p = 1
        else
            actor.attribute.autoMissileAttackRange_p = 0
        end
    end
    ActorTypeUtil:registerActorType({
        id = "毒火炮毒火状态",
        icon = "ReplaceableTextures\\CommandButtons\\BTNUnholyFrenzy.blp",
        attribute = {damage_reduction = -0.5},
        model = "Abilities\\Spells\\Undead\\UnholyFrenzy\\UnholyFrenzyTarget.mdx",
        dur = 3
    })
    actorType = ActorTypeUtil:getActorType("毒火炮")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.damage_increased = actor.level * 0.05 + 0.3
    end
    actorType.onUnitChange = function(____, actor, unit)
        local controller = _____4E3B_70AE_57FA_7840_4E8B_4EF6:onUnitChange(actor, unit)
        if controller == nil then
            return
        end
        controller.onHitTarget = function(____, projectile)
            local chance = actor.level >= 10 and 0.15 or 0.1
            if RandomUtil.isInChance(chance) then
                local actorBuff = ActorBuffUtil:addActorBuff(projectile.target, "毒火炮")
                actorBuff.attribute.damage_reduction = actor.level * -0.05 - 0.5
                actorBuff:setDur(actor.level >= 15 and 6 or 3)
            end
        end
    end
    actorType = ActorTypeUtil:getActorType("不朽甲板")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.full_property = actor.level * 1000 + 2000
    end
    actorType.onUnitDamaged = function(____, actor, damageSource, event)
        if actor.level >= 10 then
            local maxLife = UnitStateUtil:getMaxLife(actor.unit)
            if actor.level >= 15 then
                event.resultDamage = math.min(event.resultDamage, maxLife * 0.3)
            end
            if event.resultDamage > maxLife * 0.25 then
                actor:ifReady(
                    5,
                    function()
                        UnitStateUtil:addInvulnerableIfNot(actor.unit, 0.5)
                    end,
                    "无敌"
                )
            end
        end
    end
    actorType = ActorTypeUtil:getActorType("光壁")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.def_p = actor.level * 0.05 + 0.3
        actor.attribute.damage_reduction = actor.level >= 10 and 0.3 or 0
    end
    actorType.interval = 3
    actorType.onUnitInterval = function(____, actor)
        local damage = UnitStateUtil:calculateStateFormula({base = 10000, hp = 0.03}, actor.unit)
        DamageRecordUtil:damageEnemyUnitsInRange(
            actor:getName(),
            actor.unit,
            actor:get("area", 500),
            damage,
            DamageType["s_物理"]
        )
        EffectUtil:addSpecialEffectAndDestroy(
            "圆形范围伤害特效\\devilslam.mdx",
            actor.unitX,
            actor.unitY,
            actor:get("modelScale", 0.8)
        )
    end
    actorType = ActorTypeUtil:getActorType("全面覆盖")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.full_property = actor.level * 1000 + 2000
        if actor.level == 10 then
            SingletonUtil:executeOnce(
                "全面覆盖:" .. tostring(GetHandleId(actor.unit)),
                function()
                    PlayerUtil:message("全面覆盖：当前三围+10%，仅生效一次。", 5, actor.unitOwner)
                    HeroUtil:addHeroPropertyP(actor.unit, false, 0.1)
                end
            )
        end
        if actor.level == 15 then
            local str = GetHeroStr(actor.unit, false)
            local agi = GetHeroAgi(actor.unit, false)
            local int = GetHeroInt(actor.unit, false)
            local max = math.max(str, agi, int)
            SetHeroStr(actor.unit, max, true)
            SetHeroAgi(actor.unit, max, true)
            SetHeroInt(actor.unit, max, true)
            PlayerUtil:message("全面覆盖：三围最低的2个，会变得和最高的一样", 5, actor.unitOwner)
        end
    end
    actorType = ActorTypeUtil:getActorType("古老者甲板")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.full_property = actor.level * 1000 + 2000
    end
    actorType.interval = 60
    actorType.onUnitInterval = function(____, actor)
        if actor.level >= 10 then
            PlayerUtil:message("获得1%全属性加成!(绿字百分比)", 5, actor.unitOwner)
            actor.attribute.full_property_p = (actor.attribute.full_property_p or 0) + 0.01
            actor:setExtDescribe(
                "|cffcccccc当前全属性加成:",
                TextUtil:toPercentage(actor.attribute.full_property_p)
            )
        end
    end
    actorType.onUnitKillEnemy = function(____, actor, deathEnemy)
        if actor.level >= 15 then
            HeroUtil:addHeroProperty(actor.unit, 5)
        end
    end
    actorType = ActorTypeUtil:getActorType("曲率推进装置")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.move_speed = actor.level * 20 + 100
        actor.attribute.move_speed_p = actor.level >= 15 and 1 or 0
    end
    actorType.interval = 1
    actorType.onUnitInterval = function(____, actor)
        local x = actor.unitX
        local y = actor.unitY
        if MathUtil.distanceBetweenPoints(x, y, actor.lastX or 0, actor.lastY or 0) > 16 then
            BaseUtil.runLater(
                1,
                function()
                    DamageRecordUtil:damageEnemyUnitsInRange(
                        actor:getName(),
                        actor.unit,
                        actor:get("area", 300),
                        {attack = 3},
                        DamageType["s_物理"],
                        x,
                        y
                    )
                    EffectUtil:addSpecialEffectAndDestroy(
                        "圆形范围伤害特效\\devilslam.mdx",
                        x,
                        y,
                        actor:get("modelScale", 0.8)
                    )
                end,
                5,
                true
            )
        end
        actor.lastX = x
        actor.lastY = y
    end
    actorType = ActorTypeUtil:getActorType("未来装置")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.move_speed = actor.level * 5 - 100
        actor.attribute["经验倍率"] = actor.level >= 10 and 1 or 0
        actor.attribute["杀敌经验"] = actor.level >= 15 and 1 or 0
    end
    actorType.onUnitLevelChange = function(____, actor)
        PlayerUtil:message("未来装置:升级增加1%当前全属性", 5, actor.unitOwner)
        HeroUtil:addHeroPropertyP(actor.unit, false, 0.01)
    end
    actorType = ActorTypeUtil:getActorType("神避")
    actorType.onUnitDamageEnemy = function(____, actor, enemy, event)
        if HeroUtil:isHero(enemy) then
            event.resultDamage = event.resultDamage * (1 + actor.level * 5 + 0.3)
            if actor.level > 10 then
                event.resultDamage = event.resultDamage * 1.5
            end
        end
    end
    actorType.onUnitChange = function(____, actor, unit)
        local controller = _____4E3B_70AE_57FA_7840_4E8B_4EF6:onUnitChange(actor, unit)
        if controller == nil then
            return
        end
        controller.onBeforeLaunchMissile = function(____, controller, target)
            return HeroUtil:isHero(target)
        end
    end
    actorType.onUnitKillEnemy = function(____, actor, deathEnemy)
        if HeroUtil:isHero(deathEnemy) and actor.level > 15 then
            PlayerUtil:message("神避:击杀BOSS增加当前15%攻击力。", 5, actor.unitOwner)
            UnitStateUtil:addDamageBase(
                actor.unit,
                UnitStateUtil:getDamageBase(actor.unit) * 0.15
            )
        end
    end
    actorType = ActorTypeUtil:getActorType("荒火引擎")
    actorType.onActorLevelChange = function(____, actor, delta)
        actor.attribute.full_property = actor.level * 1000 + 2000
    end
    actorType.interval = 15
    actorType.onUnitInterval = function(____, actor)
        if GetUnitAbilityLevel(actor.unit, "Avul") > 0 then
            return false
        end
        actor.attribute.move_speed = 100
        SetUnitInvulnerable(actor.unit, true)
        local unit = actor.unit
        BaseUtil.runLater(
            5,
            function()
                actor.attribute.move_speed = 0
                SetUnitInvulnerable(unit, false)
            end
        )
    end
    actorType.onUnitDamageEnemy = function(____, actor, enemy, event)
        if actor.level > 15 and UnitStateUtil:isInvulnerable(actor.unit) then
            event.resultDamage = event.resultDamage * 2
        end
    end
end
_____57FA_7840_6838_5FC3_90E8_4EF6["基础强化核心部件"] = function(self, actor)
    local oldLv = actor.level
    if oldLv and oldLv >= 15 then
        ActorFrameUtil:showFailText(actor, "已经是最高等级了!", 1, actor.unitOwner)
        return false
    end
    local needGold = oldLv * 2000
    if PlayerUtil:costEnoughState(actor.unitOwner, needGold) then
        if oldLv > 5 and RandomUtil.isInChance((oldLv - 5) * 0.05) then
            if RandomUtil.isInChance(0.5) then
                if oldLv >= 13 then
                    actor.level = 10
                    actor.numberOverlay = actor.level
                    ActorFrameUtil:showTipText(actor, "|cffff0000强化失败！掉到10级", 1, actor.unitOwner)
                elseif oldLv >= 11 then
                    actor.level = 1
                    actor.numberOverlay = actor.level
                    actor.extDescribe1 = nil
                    ActorFrameUtil:showTipText(actor, "|cffff0000强化失败！掉到1级", 1, actor.unitOwner)
                else
                    ActorFrameUtil:showTipText(actor, "|cffff0000强化失败！未掉级!", 1, actor.unitOwner)
                end
            else
                ActorFrameUtil:showTipText(actor, "|cffff0000强化失败！", 1, actor.unitOwner)
            end
            return false
        else
            actor.extDescribe1 = nil
        end
        actor.level = (oldLv or 0) + 1
        actor.numberOverlay = actor.level
        actor.extDescribeLast1 = (("|cffccccccLv" .. tostring(actor.level)) .. "强化成功几率为") .. TextUtil:toPercentage(1 - (actor.level - 5) * 0.05)
        ActorFrameUtil:showTipText(
            actor,
            "|cff00ff00强化成功!Lv" .. tostring(actor.level),
            1,
            actor.unitOwner
        )
        return true
    else
        ActorFrameUtil:showTipText(
            actor,
            "|cffff0000金币不足！需要" .. tostring(needGold),
            1,
            actor.unitOwner
        )
        return false
    end
end
return ____exports
